INSERT INTO file_contents (id, file_id, chunk_index, chunk_content, chunk_metadata, char_count, token_count, created_at) VALUES
('c3000001-0000-0000-0000-000000000001', 'b2000001-0000-0000-0000-000000000001', 0, '云盘智能体项目需求文档\n\n版本：v1.0\n\n1. 项目背景\n为了解决企业云盘文件管理效率低下的问题，我们计划开发一款基于AI大模型的云盘智能体应用。该应用将集成文件管理、智能分类、语义搜索、文档问答等功能，提升用户的工作效率。\n\n2. 功能需求\n2.1 文件管理\n- 支持文件上传、下载、删除、重命名\n- 支持文件分片上传\n- 支持文件版本管理\n- 支持文件分享和权限控制', '{"language": "zh", "file_type": "document"}', 312, 256, '2026-07-01 09:05:00+08'),
('c3000001-0000-0000-0000-000000000002', 'b2000001-0000-0000-0000-000000000001', 1, '2.2 智能分类\n- 自动识别文件类型（文档、图片、视频、音频等）\n- 自动提取文件标签\n- 自动生成文件摘要\n- 智能文件夹分类\n\n2.3 语义搜索\n- 支持自然语言搜索\n- 支持模糊搜索和精确搜索\n- 支持按文件类型、时间、标签多维度筛选\n- 搜索结果显示文件摘要和关键词高亮', '{"language": "zh", "file_type": "document"}', 245, 198, '2026-07-01 09:05:00+08'),
('c3000001-0000-0000-0000-000000000003', 'b2000001-0000-0000-0000-000000000001', 2, '2.4 文档问答\n- 支持基于文件内容的问答\n- 支持多文档联合问答\n- 支持上下文关联追问\n- 支持回答引用来源标注\n\n3. 技术指标\n- 文件上传速度：≤5秒（100MB以内）\n- 语义搜索响应时间：≤3秒\n- 文档问答准确率：≥90%\n- 系统可用性：99.9%', '{"language": "zh", "file_type": "document"}', 215, 175, '2026-07-01 09:05:00+08'),
('c3000001-0000-0000-0000-000000000004', 'b2000001-0000-0000-0000-000000000003', 0, 'WebDAV云盘接入文档\n\n1. 概述\nWebDAV协议提供了一组标准HTTP扩展方法，方便客户端连接云盘服务。\n\n2. 认证方式\n采用HTTP Basic认证，支持用户名和密码连接。\n\n3. 方法列表\n- 文件列表：PROPFIND\n- 文件上传：PUT\n- 文件下载：GET\n- 文件删除：DELETE', '{"language": "zh", "file_type": "document"}', 298, 189, '2026-07-02 08:15:00+08'),
('c3000001-0000-0000-0000-000000000005', 'b2000001-0000-0000-0000-000000000003', 1, '4. 接口规范\n所有接口请求和响应均使用JSON格式。\n\n5. 错误处理\n统一的错误码规范，包含错误码、错误消息和错误详情。\n\n6. 限流策略\n每个API Key每分钟最多调用100次。\n\n7. 最佳实践\n- 使用连接池管理HTTP连接\n- 实现指数退避重试机制\n- 缓存access_token减少认证请求', '{"language": "zh", "file_type": "document"}', 245, 156, '2026-07-02 08:15:00+08'),
('c3000001-0000-0000-0000-000000000006', 'b2000001-0000-0000-0000-000000000004', 0, '2026年7月1日项目启动会议纪要\n\n参会人员：张三、李四、王五、赵六\n\n会议内容：\n1. 项目背景介绍\n2. 技术方案评审\n3. 任务分工\n4. 时间节点确认\n\n决议事项：\n- 采用双服务架构（Java后端+Python AI服务）\n- 数据库选用PostgreSQL\n- 消息队列选用RabbitMQ\n- 第一阶段目标：完成API凭证获取和架构设计', '{"language": "zh", "file_type": "text"}', 278, 178, '2026-07-02 09:02:00+08'),
('c3000001-0000-0000-0000-000000000007', 'b2000001-0000-0000-0000-000000000005', 0, '智能分类算法设计\n\n1. 概述\n基于大模型（LLM）实现文件智能分类，自动识别文件类型、提取标签、生成摘要。\n\n2. 分类流程\n输入文件 → 文件类型识别 → 内容提取 → LLM分类 → 标签生成 → 摘要生成 → 存储结果\n\n3. 分类体系\n- 一级分类：文档、图片、视频、音频、其他\n- 二级分类：技术文档、管理文档、设计稿、报表等\n\n4. 使用的模型\n- 元景-70B：文本分类和摘要生成\n- 元景图文问答-80B：图片内容理解', '{"language": "zh", "file_type": "document"}', 320, 234, '2026-07-03 10:20:00+08'),
('c3000001-0000-0000-0000-000000000008', 'b2000001-0000-0000-0000-000000000005', 1, '5. 标签提取策略\n- 技术文档：提取编程语言、框架、技术栈等标签\n- 管理文档：提取项目名、阶段、负责人等标签\n- 设计稿：提取界面类型、风格、组件等标签\n\n6. 摘要生成策略\n- 短文档（<1000字）：全文摘要\n- 长文档（>1000字）：分段摘要后合并\n\n7. 性能优化\n- 使用异步处理，上传后立即返回\n- 批量处理减少API调用次数\n- 缓存常见文件类型的分类结果', '{"language": "zh", "file_type": "document"}', 298, 212, '2026-07-03 10:20:00+08'),
('c3000001-0000-0000-0000-000000000009', 'b2000001-0000-0000-0000-000000000006', 0, 'RAG检索增强生成技术方案\n\n1. 概述\nRAG（Retrieval-Augmented Generation）是一种结合检索和生成的AI技术方案。\n\n2. 系统架构\n用户查询 → 查询向量化 → 向量检索 → 文档重排序 → LLM生成 → 返回结果\n\n3. 向量化模型\n- Jina-embedding-v4：文本向量化\n- Qwen3-VL-Embedding-8B：多模态向量化\n\n4. 重排序模型\n- Qwen3-VL-Reranker-8B：结果相关性排序', '{"language": "zh", "file_type": "document"}', 289, 190, '2026-07-03 14:30:00+08'),
('c3000001-0000-0000-0000-000000000010', 'b2000001-0000-0000-0000-000000000006', 1, '5. 混合检索策略\n- BM25全文检索 + 向量语义检索 + 重排序\n- 支持关键词精确匹配和语义相似度匹配\n\n6. 文档分片策略\n- 按段落分片，每个分片不超过512 tokens\n- 保留上下文关联（相邻分片重叠10%）\n\n7. 检索优化\n- 多路召回：同时使用BM25和向量检索\n- 重排序：使用Reranker模型提升排序准确性\n- 结果过滤：按时间、文件类型过滤', '{"language": "zh", "file_type": "document"}', 278, 198, '2026-07-03 14:30:00+08'),
('c3000001-0000-0000-0000-000000000011', 'b2000001-0000-0000-0000-000000000007', 0, '云盘智能体产品需求文档 v2.0\n\n一、产品概述\n云盘智能体是一款基于AI大模型的智能云盘应用，提供文件管理、智能分类、语义搜索、文档问答等功能。\n\n二、目标用户\n- 企业员工：日常文件管理和协作\n- 知识工作者：文档检索和知识管理\n- 管理者：团队文件共享和权限管理\n\n三、核心功能\n1. 文件管理：上传、下载、删除、重命名、移动\n2. 智能分类：自动分类、标签、摘要', '{"language": "zh", "file_type": "spreadsheet"}', 312, 202, '2026-07-04 09:10:00+08'),
('c3000001-0000-0000-0000-000000000012', 'b2000001-0000-0000-0000-000000000007', 1, '3. 语义搜索：自然语言搜索、多维度筛选\n4. 文档问答：基于文件内容的智能问答\n5. 内容生成：自动生成摘要、报告、PPT\n\n四、非功能需求\n1. 性能：响应时间<3秒\n2. 安全：数据加密、访问控制\n3. 可用性：99.9%\n4. 可扩展性：支持水平扩展\n\n五、里程碑\n- W1-W2：需求分析与架构设计\n- W3-W4：核心开发\n- W5-W6：功能开发\n- W7-W8：集成测试与演示', '{"language": "zh", "file_type": "spreadsheet"}', 289, 215, '2026-07-04 09:10:00+08'),
('c3000001-0000-0000-0000-000000000013', 'b2000001-0000-0000-0000-000000000010', 0, '项目开发计划甘特图\n\n第一阶段：需求分析与架构设计（W1-W2）\n- 任务0：API凭证获取（W1优先）\n- 任务1：系统架构设计\n- 任务2：数据库设计\n- 任务3：云盘API对接方案设计\n\n第二阶段：核心开发（W3-W4）\n- 任务4：后端服务框架搭建\n- 任务5：文件管理模块开发\n- 任务6：云盘API对接实现', '{"language": "zh", "file_type": "spreadsheet"}', 256, 168, '2026-07-05 09:05:00+08'),
('c3000001-0000-0000-0000-000000000014', 'b2000001-0000-0000-0000-000000000012', 0, '后端API接口规范文档\n\n1. 通用规范\n- 基础URL：/api/v1\n- 请求/响应格式：JSON\n- 认证方式：Bearer Token（JWT）\n\n2. 文件管理接口\n- POST /api/v1/files/upload：上传文件\n- GET /api/v1/files：获取文件列表\n- GET /api/v1/files/{id}：获取文件详情\n- DELETE /api/v1/files/{id}：删除文件\n\n3. 搜索接口\n- POST /api/v1/search：语义搜索\n- GET /api/v1/search/history：搜索历史', '{"language": "zh", "file_type": "document"}', 312, 210, '2026-07-05 11:15:00+08'),
('c3000001-0000-0000-0000-000000000015', 'b2000001-0000-0000-0000-000000000012', 1, '4. 问答接口\n- POST /api/v1/qa/ask：提问\n- GET /api/v1/qa/history：问答历史\n\n5. 内容生成接口\n- POST /api/v1/generate/summary：生成摘要\n- POST /api/v1/generate/report：生成报告\n\n6. 认证接口\n- POST /api/v1/auth/login：登录\n- POST /api/v1/auth/refresh：刷新token\n- POST /api/v1/auth/logout：登出\n\n7. 错误码规范\n- 200：成功\n- 400：请求参数错误\n- 401：未认证\n- 403：无权限\n- 404：资源不存在\n- 500：服务器内部错误', '{"language": "zh", "file_type": "document"}', 345, 278, '2026-07-05 11:15:00+08'),
('c3000001-0000-0000-0000-000000000016', 'b2000001-0000-0000-0000-000000000013', 0, '前端开发规范与最佳实践\n\n1. 技术栈\n- 框架：React 18 + TypeScript\n- 状态管理：Zustand\n- UI组件库：Ant Design 5\n- HTTP请求：Axios\n\n2. 代码规范\n- 使用ESLint + Prettier\n- 组件命名：PascalCase\n- 函数命名：camelCase\n- 常量命名：UPPER_SNAKE_CASE\n\n3. 目录结构\n- src/components：通用组件\n- src/pages：页面组件\n- src/services：API服务\n- src/hooks：自定义hooks', '{"language": "zh", "file_type": "document"}', 312, 225, '2026-07-06 08:10:00+08'),
('c3000001-0000-0000-0000-000000000017', 'b2000001-0000-0000-0000-000000000017', 0, '系统运维手册\n\n1. 系统架构\n本项目采用微服务架构，包含Java后端服务、Python AI服务和前端应用。\n\n2. 部署环境\n- 生产环境：Kubernetes集群\n- 开发环境：Docker Compose\n\n3. 监控告警\n- 使用Prometheus + Grafana\n- 关键指标：CPU、内存、磁盘、网络\n- 告警规则：CPU>80%、内存>85%、磁盘>90%\n\n4. 日志管理\n- 使用ELK Stack\n- 日志保留策略：30天\n- 审计日志保留：180天', '{"language": "zh", "file_type": "document"}', 324, 234, '2026-07-07 10:30:00+08'),
('c3000001-0000-0000-0000-000000000018', 'b2000001-0000-0000-0000-000000000019', 0, '竞品分析报告\n\n1. 竞品概述\n- 百度网盘智能助手\n- 阿里云盘AI助手\n- 腾讯微云\n- 坚果云\n\n2. 功能对比\n| 功能 | 本产品 | 百度网盘 | 阿里云盘 | 腾讯微云 |\n|------|--------|---------|---------|---------|\n| 智能分类 | ✅ | ❌ | ❌ | ❌ |\n| 语义搜索 | ✅ | ❌ | ❌ | ❌ |\n| 文档问答 | ✅ | ❌ | ❌ | ❌ |\n| 内容生成 | ✅ | ❌ | ❌ | ❌ |', '{"language": "zh", "file_type": "document"}', 289, 198, '2026-07-08 09:30:00+08'),
('c3000001-0000-0000-0000-000000000019', 'b2000001-0000-0000-0000-000000000020', 0, '2026年Q2安全审计报告\n\n1. 审计范围\n- 代码安全审查\n- 依赖安全扫描\n- 数据安全评估\n- 访问控制审计\n\n2. 发现的问题\n- 3个高危漏洞（已修复）\n- 8个中危漏洞（已修复）\n- 12个低危漏洞（已修复）\n\n3. 改进建议\n- 定期进行安全扫描\n- 加强API鉴权机制\n- 实施数据脱敏策略\n- 完善日志审计', '{"language": "zh", "file_type": "document"}', 278, 189, '2026-07-08 10:20:00+08'),
('c3000001-0000-0000-0000-000000000020', 'b2000001-0000-0000-0000-000000000021', 0, '云盘智能体用户操作手册\n\n1. 快速开始\n1.1 登录系统\n打开浏览器访问系统地址，输入用户名和密码登录。\n\n1.2 上传文件\n点击"上传文件"按钮，选择文件或拖拽文件到上传区域。\n\n1.3 搜索文件\n在搜索框输入自然语言描述，如"找一下上周的会议纪要"。\n\n2. 功能介绍\n2.1 文件管理\n支持文件的上传、下载、删除、重命名、移动等操作。', '{"language": "zh", "file_type": "document"}', 298, 198, '2026-07-08 14:30:00+08'),
('c3000001-0000-0000-0000-000000000021', 'b2000001-0000-0000-0000-000000000021', 1, '2.2 智能分类\n系统会自动识别文件类型，并生成标签和摘要。\n\n2.3 语义搜索\n支持自然语言搜索，如"帮我找一下关于数据库设计的文档"。\n\n2.4 文档问答\n选中文件后点击"提问"，输入问题，系统会基于文件内容回答。\n\n2.5 内容生成\n支持自动生成文件摘要、工作报告和PPT演示文稿。\n\n3. 常见问题\nQ: 支持哪些文件格式？\nA: 支持文档、图片、视频、音频等常见格式。', '{"language": "zh", "file_type": "document"}', 312, 215, '2026-07-08 14:30:00+08'),
('c3000001-0000-0000-0000-000000000022', 'b2000001-0000-0000-0000-000000000022', 0, '云盘市场调研数据\n\n1. 市场规模\n2026年中国企业云盘市场规模预计达到150亿元，同比增长30%。\n\n2. 用户需求\n- 文件管理：85%的用户关注\n- 文件搜索：72%的用户关注\n- 文件协作：68%的用户关注\n- 安全控制：65%的用户关注\n\n3. 竞品分析\n- 百度网盘：市场份额35%\n- 阿里云盘：市场份额25%\n- 腾讯微云：市场份额15%\n- 其他：市场份额25%', '{"language": "zh", "file_type": "spreadsheet"}', 287, 198, '2026-07-09 09:15:00+08'),
('c3000001-0000-0000-0000-000000000023', 'b2000001-0000-0000-0000-000000000021', 2, '4. 常见问题\nQ: 支持哪些文件格式？\nA: 支持文档、图片、视频、音频等常见格式。\nQ: 文件上传大小限制？\nA: 单文件最大支持100MB。\nQ: 是否支持移动端？\nA: 支持响应式设计，可在手机浏览器使用。\n\n5. 联系我们\n如有问题请联系技术支持。', '{"language": "zh", "file_type": "document"}', 198, 145, '2026-07-08 14:30:00+08'),
('c3000001-0000-0000-0000-000000000024', 'b2000001-0000-0000-0000-000000000007', 2, '五、里程碑\n- W1-W2：需求分析与架构设计\n- W3-W4：核心开发\n- W5-W6：功能开发\n- W7-W8：集成测试与演示\n\n六、风险控制\n1. 技术风险：AI模型API不稳定 -> 多模型降级\n2. 进度风险：需求变更 -> 敏捷迭代\n3. 资源风险：人员不足 -> 合理调配', '{"language": "zh", "file_type": "spreadsheet"}', 198, 145, '2026-07-04 09:10:00+08');
