INSERT INTO semantic_indexes (id, file_id, chunk_index, chunk_text, embedding, metadata, created_at) VALUES
('f6000001-0000-0000-0000-000000000001', 'b2000001-0000-0000-0000-000000000001', 0, '云盘智能体项目需求文档 版本 项目背景 为了解决企业云盘文件管理效率低下的问题 我们计划开发一款基于AI大模型的云盘智能体应用', 'emb_001_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-01 09:10:00+08'),
('f6000001-0000-0000-0000-000000000002', 'b2000001-0000-0000-0000-000000000001', 1, '智能分类 自动识别文件类型 文档 图片 视频 音频 自动提取文件标签 自动生成文件摘要 智能文件夹分类 语义搜索 支持自然语言搜索', 'emb_001_002', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-01 09:10:00+08'),
('f6000001-0000-0000-0000-000000000003', 'b2000001-0000-0000-0000-000000000001', 2, '文档问答 支持基于文件内容的问答 支持多文档联合问答 支持上下文关联追问 技术指标 文件上传速度 语义搜索响应时间', 'emb_001_003', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-01 09:10:00+08'),
('f6000001-0000-0000-0000-000000000004', 'b2000001-0000-0000-0000-000000000003', 0, 'WebDAV云盘接入文档 概述 提供标准HTTP扩展方法 支持Basic认证 PROPFIND文件列表 PUT上传 GET下载 DELETE删除', 'emb_003_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-02 08:20:00+08'),
('f6000001-0000-0000-0000-000000000005', 'b2000001-0000-0000-0000-000000000003', 1, '接口规范 所有接口请求和响应均使用JSON格式 错误处理 统一的错误码规范 限流策略 每个API Key每分钟最多调用100次', 'emb_003_002', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-02 08:20:00+08'),
('f6000001-0000-0000-0000-000000000006', 'b2000001-0000-0000-0000-000000000005', 0, '智能分类算法设计 基于大模型实现文件智能分类 自动识别文件类型 提取标签 生成摘要 分类流程 输入文件 文件类型识别 内容提取', 'emb_005_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-03 10:25:00+08'),
('f6000001-0000-0000-0000-000000000007', 'b2000001-0000-0000-0000-000000000005', 1, '标签提取策略 技术文档提取编程语言 框架 技术栈等标签 管理文档提取项目名 阶段 负责人等标签 摘要生成策略 短文档全文摘要 长文档分段摘要', 'emb_005_002', '{"model": "qwen3-vl-embedding-8b", "embedding_dim": 1024, "language": "zh"}', '2026-07-03 10:25:00+08'),
('f6000001-0000-0000-0000-000000000008', 'b2000001-0000-0000-0000-000000000006', 0, 'RAG检索增强生成技术方案 结合检索和生成的AI技术方案 用户查询 查询向量化 向量检索 文档重排序 LLM生成 返回结果', 'emb_006_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-03 14:35:00+08'),
('f6000001-0000-0000-0000-000000000009', 'b2000001-0000-0000-0000-000000000006', 1, '混合检索策略 BM25全文检索 向量语义检索 重排序 支持关键词精确匹配和语义相似度匹配 文档分片策略 按段落分片 每个分片不超过512 tokens', 'emb_006_002', '{"model": "qwen3-vl-embedding-8b", "embedding_dim": 1024, "language": "zh"}', '2026-07-03 14:35:00+08'),
('f6000001-0000-0000-0000-000000000010', 'b2000001-0000-0000-0000-000000000007', 0, '云盘智能体产品需求文档 产品概述 基于AI大模型的智能云盘应用 提供文件管理 智能分类 语义搜索 文档问答 目标用户 企业员工 知识工作者', 'emb_007_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-04 09:15:00+08'),
('f6000001-0000-0000-0000-000000000011', 'b2000001-0000-0000-0000-000000000007', 1, '语义搜索 自然语言搜索 多维度筛选 文档问答 基于文件内容的智能问答 内容生成 自动生成摘要 报告 非功能需求 性能 安全 可用性', 'emb_007_002', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-04 09:15:00+08'),
('f6000001-0000-0000-0000-000000000012', 'b2000001-0000-0000-0000-000000000012', 0, '后端API接口规范文档 通用规范 基础URL 请求响应格式JSON 认证方式Bearer Token 文件管理接口 上传文件 获取文件列表 获取文件详情', 'emb_012_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-05 11:20:00+08'),
('f6000001-0000-0000-0000-000000000013', 'b2000001-0000-0000-0000-000000000012', 1, '问答接口 提问 问答历史 内容生成接口 生成摘要 生成报告 认证接口 登录 刷新token 登出 错误码规范 200成功 400参数错误 401未认证', 'emb_012_002', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-05 11:20:00+08'),
('f6000001-0000-0000-0000-000000000014', 'b2000001-0000-0000-0000-000000000017', 0, '系统运维手册 系统架构 微服务架构 包含Java后端服务 Python AI服务和前端应用 部署环境 生产环境Kubernetes集群 开发环境Docker Compose', 'emb_017_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-07 10:35:00+08'),
('f6000001-0000-0000-0000-000000000015', 'b2000001-0000-0000-0000-000000000019', 0, '竞品分析报告 百度网盘智能助手 阿里云盘AI助手 腾讯微云 坚果云 功能对比 智能分类 语义搜索 文档问答 内容生成', 'emb_019_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-08 09:35:00+08'),
('f6000001-0000-0000-0000-000000000016', 'b2000001-0000-0000-0000-000000000020', 0, '安全审计报告 审计范围 代码安全审查 依赖安全扫描 数据安全评估 访问控制审计 发现的问题 3个高危漏洞已修复 8个中危漏洞已修复', 'emb_020_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-08 10:25:00+08'),
('f6000001-0000-0000-0000-000000000017', 'b2000001-0000-0000-0000-000000000021', 0, '云盘智能体用户操作手册 快速开始 登录系统 打开浏览器访问系统地址 输入用户名和密码登录 上传文件 点击上传文件按钮 选择文件或拖拽文件', 'emb_021_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-08 14:35:00+08'),
('f6000001-0000-0000-0000-000000000018', 'b2000001-0000-0000-0000-000000000021', 1, '智能分类 系统会自动识别文件类型 并生成标签和摘要 语义搜索 支持自然语言搜索 文档问答 选中文件后点击提问 输入问题 系统会基于文件内容回答', 'emb_021_002', '{"model": "qwen3-vl-embedding-8b", "embedding_dim": 1024, "language": "zh"}', '2026-07-08 14:35:00+08'),
('f6000001-0000-0000-0000-000000000019', 'b2000001-0000-0000-0000-000000000022', 0, '云盘市场调研数据 市场规模 2026年中国企业云盘市场规模预计达到150亿元 同比增长30% 用户需求 文件管理85% 文件搜索72% 文件协作68%', 'emb_022_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-09 09:20:00+08'),
('f6000001-0000-0000-0000-000000000020', 'b2000001-0000-0000-0000-000000000004', 0, '项目启动会议纪要 参会人员 张三 李四 王五 赵六 会议内容 项目背景介绍 技术方案评审 任务分工 时间节点确认 决议事项 双服务架构', 'emb_004_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-02 09:05:00+08'),
('f6000001-0000-0000-0000-000000000021', 'b2000001-0000-0000-0000-000000000013', 0, '前端开发规范与最佳实践 技术栈 React 18 TypeScript 状态管理 Zustand UI组件库 Ant Design 5 HTTP请求 Axios 代码规范 ESLint Prettier', 'emb_013_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-06 08:15:00+08'),
('f6000001-0000-0000-0000-000000000022', 'b2000001-0000-0000-0000-000000000010', 0, '项目开发计划甘特图 第一阶段 需求分析与架构设计 任务0 API凭证获取 任务1 系统架构设计 任务2 数据库设计 第二阶段 核心开发 任务4 后端服务框架搭建', 'emb_010_001', '{"model": "jina-embedding-v4", "embedding_dim": 768, "language": "zh"}', '2026-07-05 09:10:00+08');
